const T=String.raw;
const s=(text,math)=>({text,math});
const E=(topic,title,slide,problem,hint,solution,takeaway,trap,practice)=>({topic,title,slide,kind:topic===0||topic===4||topic===6?'Theory + computation':'Computation',problem,hint,solution,takeaway,trap,practice});
export const examples=[
E(0,'Select for generalization, not memorization',15,
'Candidate A has training error 1 and validation error 5. Candidate B has training error 2 and validation error 3 on the same split and metric. Which is the better development choice, and why?',
'Separate training fit from the evidence used to choose a model.',
[s('Compare the validation errors: B’s 3 is lower than A’s 5.'),s('Notice that A fits the training set better, but that advantage does not transfer to this validation set.'),s('Choose B provisionally using validation evidence. Keep the test set untouched for final evaluation.')],
'A higher training error can accompany better generalization. One comparison is evidence, not proof that B wins on every future sample.',
'Do not select the model by training error alone or inspect test results repeatedly while tuning.',
{problem:'Model C has both training and validation error near 20, while other reasonable models achieve errors near 3. Is stronger regularization the first conclusion?',solution:[s('High error on both sets suggests underfitting, optimization failure, or another data/model problem.'),s('Increasing regularization could further limit fitting. Check capacity, optimization and data quality before treating this as overfitting.')]}),
E(1,'Compare objectives with an L2 penalty',5,
T`Model A has data loss 1 and scalar weight $\theta=3$. Model B has data loss 2 and weight $\theta=1$. With $\lambda=1/2$ and $J=L+\lambda\theta^2$, which objective is smaller?`,
'Compute the penalty for each model before adding the fitting loss.',
[s('Model A’s large weight receives a larger squared penalty.',T`J_A=1+\frac12(3^2)=\frac{11}{2}`),s('Compute B with exactly the same convention.',T`J_B=2+\frac12(1^2)=\frac52`),s('The penalized objective prefers B, even though B has a higher data-fitting loss. Validation evidence is still needed to assess generalization.')],
'The penalty changes the tradeoff used during training; it does not directly report validation performance.',
'Check the coefficient and whether the penalty includes a factor of 1/2. Do not silently change conventions.',
{problem:T`For $\theta=(1,-2)$ and $\lambda=1$, compute the L1 penalty, L2 penalty and L2 penalty gradient.`,solution:[s('Sum absolute values for L1, and squares for L2.',T`\Omega_{L1}=1+2=3,\qquad\Omega_{L2}=1+4=5`),s('Differentiate the L2 penalty in this convention.',T`\nabla\Omega_{L2}=2\theta=(2,-4)`)]}),
E(2,'Rank likelihoods without calculating logarithms',10,
T`For two independent discrete observations, A assigns probabilities $(1/2,1/2)$ and B assigns $(1/4,3/4)$. Which has the greater likelihood and lower negative log-likelihood?`,
'Multiply the probabilities and use monotonicity of the logarithm.',
[s('Independence makes each model’s likelihood a product.',T`p(\mathcal D\mid A)=\frac12\frac12=\frac14`),s('Compute B using the same observations.',T`p(\mathcal D\mid B)=\frac14\frac34=\frac3{16}`),s('Since 1/4 = 4/16 exceeds 3/16, A has higher likelihood. Log preserves that ordering; negative log reverses it, so A has lower NLL.')],
'You can rank the models using fractions; there is no need to approximate logarithms.',
'The product factorization assumes independence in the model. Do not add probabilities in place of multiplying them.',
{problem:T`Two Gaussian regression models have residuals $(1,-1)$ and $(0,2)$, with the same fixed variance and dataset size. Which has lower NLL?`,solution:[s('Compare sums of squared residuals.',T`\mathrm{SSE}_A=1+1=2,\qquad\mathrm{SSE}_B=0+4=4`),s('Both objectives have the same positive SSE multiplier and normalization term. A therefore has lower NLL without evaluating the Gaussian constants.')]}),
E(3,'Let a prior change the preferred parameters',13,
T`Candidate A has likelihood $1/2$ and prior density $1/4$. Candidate B has likelihood $1/4$ and prior density 1. Compare the MLE and MAP choices for this fixed model and dataset.`,
'MAP compares likelihood times prior; the common evidence cancels.',
[s('MLE considers only likelihood, so it prefers A.'),s('Compute the unnormalized posterior scores.',T`u_A=\frac12\frac14=\frac18,\qquad u_B=\frac14(1)=\frac14`),s('MAP prefers B because its posterior score is larger. Dividing both scores by the same evidence would not change that ordering.')],
'A prior can outweigh a likelihood advantage; it is a preference over parameter settings, not additional observed examples.',
'Do not reverse likelihood and posterior. The conditional expressions refer to different quantities.',
{problem:T`A zero-mean isotropic Gaussian prior has variance $\tau^2=2$. Before rescaling the data loss, what is the coefficient of $\|\theta\|_2^2$ in its negative log-density?`,solution:[s('Use the isotropic Gaussian quadratic coefficient.',T`\lambda=\frac1{2\tau^2}=\frac14`),s('With a smaller prior variance the coefficient would grow, reflecting a stronger preference for weights near zero.')]}),
E(4,'Decide what a flip must change',21,
'You propose horizontally flipping every training image while keeping every label unchanged. Evaluate this rule for dog/cat classification, character recognition, and object detection.',
'Ask whether the target is an identity or a spatial annotation.',
[s('Dog/cat classification often preserves class identity under a horizontal flip, assuming the task and data support that invariance.'),s('For characters, a flip may change the symbol’s meaning; keeping the original label can create incorrect supervision.'),s('For detection, a flip can be valid if bounding boxes are transformed with the pixels. Label-preserving classification does not imply unchanged coordinates.')],
'The correct augmentation rule depends on the task and its target representation.',
'Do not put augmented copies of one original into both training and validation splits.',
{problem:T`Supplementary coordinate example: an image spans x-coordinates 0 through 8, and a box spans $[1,3]$. After a horizontal reflection $x'=8-x$, what is the new ordered box interval?`,solution:[s('Reflect the endpoints: 1 maps to 7 and 3 maps to 5.'),s('Order left before right.',T`[x'_{\min},x'_{\max}]=[8-3,8-1]=[5,7]`)]}),
E(5,'Keep the mixed label consistent',28,
T`Bird and cat targets are $y_1=(1,0)$ and $y_2=(0,1)$. MixUp uses $\lambda=3/4$. At one pixel $x_1=4$ and $x_2=0$. Find the mixed pixel and target, then compare with CutMix that replaces a 2-by-2 patch in a 4-by-4 bird image.`,
'MixUp uses the mixing weight directly; CutMix derives it from retained area.',
[s('Blend the pixel under MixUp.',T`\tilde x=\frac34(4)+\frac14(0)=3`),s('Blend the class vector by the same coefficient.',T`\tilde y=\frac34(1,0)+\frac14(0,1)=(\tfrac34,\tfrac14)`),s('For CutMix, the cat patch contributes 4 of 16 pixels. The bird keeps 12 of 16.',T`\lambda=\frac{12}{16}=\frac34`),s('The target weights are the same in this example, but the inputs differ: MixUp blends every pixel; CutMix replaces a spatial patch.')],
'The same soft target can accompany two very different input constructions.',
'The CutMix coefficient must match the actual retained area, including any patch clipping at image boundaries.',
{problem:T`A 4-by-4 bird image receives a 2-by-1 cat patch. What is the bird/cat target? What would ordinary CutOut do to the target if it erased that patch instead?`,solution:[s('The cat patch occupies 2 of 16 pixels.',T`\tilde y=(\tfrac{14}{16},\tfrac2{16})=(\tfrac78,\tfrac18)`),s('Ordinary CutOut usually keeps the original bird target (1,0), assuming enough evidence remains; it does not introduce a second class target.')]}),
E(6,'Agreement is useful only with informative learning',30,
'Two augmented views of a cat receive predictions (1,0) and (1,0), where the class order is bird, cat. A classmate says perfect agreement means the model has solved the task. Assess the claim.',
'Check agreement and correctness separately.',
[s('Both predictions agree, but both assign all probability to bird, which is the wrong target.'),s('A constant classifier could agree on every pair of views and still be useless.'),s('Agreement must be combined with informative task supervision. AgMax adds an agreement constraint; it does not replace the need to learn accurate representations.')],
'Agreement concerns consistency across views; supervised loss concerns whether those predictions match the target.',
'Do not identify AgMax with a made-up squared-difference formula as if it were the exact paper objective.',
{problem:'An experiment uses RandAugment to choose two transformations, then encourages the resulting views to agree. Which part selects the views and which part constrains the responses?',solution:[s('RandAugment supplies the transformation-selection policy.'),s('The agreement constraint influences the learned representations or predictions. Choosing transforms and penalizing disagreement are different operations.')]}),
E(7,'Measure sensitivity to a weight perturbation',38,
T`In the illustrative scalar model $f(x;w)=wx$, let $w=2$ and $x=2$. A sampled weight perturbation is equally likely to be $-1/2$ or $+1/2$. Compute the clean prediction, two perturbed predictions and their average.`,
'Perturb the weight before multiplying by the fixed input.',
[s('Compute the clean prediction.',T`f(2;2)=4`),s('The two possible weights are 3/2 and 5/2.',T`f(2;3/2)=3,\qquad f(2;5/2)=5`),s('Average over the equally likely perturbations.',T`\mathbb E[f]=\frac12(3)+\frac12(5)=4`),s('The average matches here because the model is linear and the perturbation has zero mean. Individual predictions still change; nonlinear networks need not preserve the average output.')],
'Robustness concerns sensitivity to perturbations, not merely whether the average perturbation is zero.',
'Zero-mean noise does not imply zero change in a nonlinear prediction or in expected loss.',
{problem:T`Keep the clean target at 4. What is the expected squared error caused by the two perturbed predictions 3 and 5?`,solution:[s('Each perturbation is one unit away from the target.',T`(3-4)^2=(5-4)^2=1`),s('The expected squared error is 1 even though the mean prediction remains 4.',T`\mathbb E[(f-y)^2]=\tfrac12(1)+\tfrac12(1)=1`)]}),
E(8,'Balance the contributions of related tasks',39,
T`A shared-backbone model has classification loss 2 and box-regression loss 4. With weights 1 and $1/2$, compute the joint loss and explain where the two learning signals meet.`,
'Weight each loss before summing; shared weights receive both gradient contributions.',
[s('The classification contribution is 1 × 2 = 2.'),s('The box-regression contribution is (1/2) × 4 = 2.',T`J=2+\frac12(4)=4`),s('Both tasks influence the shared backbone. Each task-specific head also has its own parameters and gradient path.')],
'Loss weighting changes the relative influence of tasks; a low total does not by itself establish that every task improved.',
'Related tasks can still conflict. Check per-task validation behavior and the numerical scales of their losses.',
{problem:T`Supplementary gradient example: on one shared weight, task gradients are 2 and −4. The task weights are 1 and $1/2$. What is their combined gradient?`,solution:[s('Differentiate the weighted sum by adding the weighted gradients.',T`g=1(2)+\frac12(-4)=0`),s('The contributions cancel on this coordinate even though each task gradient is nonzero. This illustrates possible task conflict.')]}),
E(9,'Count distinct parameters, not branches',40,
'A two-branch system uses encoders with 12 parameters each and a separate comparison head with 4 parameters. Compare the number of distinct trainable parameters with independent versus tied encoders.',
'A tied parameter is one stored trainable quantity used more than once.',
[s('Independent encoders contribute 12 + 12 parameters, plus the comparison head.',T`P_{\rm independent}=12+12+4=28`),s('Tied encoders share a single set of 12 parameters.',T`P_{\rm tied}=12+4=16`),s('Both images still need to be processed. Sharing reduces distinct encoder parameters, not necessarily the number of forward computations.')],
'Architecture copying is different from actual weight tying.',
'Include separate heads in the count. Do not assume the whole model’s parameter count is exactly halved.',
{problem:T`The shared encoder is $f(x;\theta)=\theta x$ with $\theta=2$. Inputs are 3 and 5. Must the two outputs match?`,solution:[s('Apply the same weights to the different inputs.',T`h_1=2(3)=6,\qquad h_2=2(5)=10`),s('The outputs differ. Shared parameters enforce the same mapping, not identical representations for different inputs.')]}),
E(10,'Use patience but restore the best weights',41,
'Validation losses at epochs 1–5 are 5, 3, 2, 2, 4. Improvements must be strict; patience is two consecutive non-improving checks. When do we stop, and which checkpoint do we restore?',
'An equal loss does not improve under the stated strict rule.',
[s('Epochs 1–3 set progressively better losses; the best checkpoint is epoch 3.'),s('Epoch 4 ties the best, so the non-improvement count becomes 1. Epoch 5 is worse, making the count 2.'),s('Stop at epoch 5 and restore epoch 3. The checkpoint that triggers stopping is not automatically the selected checkpoint.')],
'Patience handles fluctuations; the best-metric rule chooses the final checkpoint.',
'Specify ties and minimum improvement. Different conventions can change the stopping epoch.',
{problem:T`If the monitored metric is accuracy and the scores are $1/2,3/4,5/8$, which checkpoint is best?`,solution:[s('Accuracy is maximized, so use the largest score.'),s('Since 3/4 = 6/8 exceeds 5/8, epoch 2 is best. Do not apply a loss-minimization rule blindly.')]}),
E(11,'Keep probability determines dropout scaling',43,
T`Use inverted dropout on activation $h=4$ with keep probability $p=1/2$. Find its possible training outputs, expected training output and ordinary evaluation output.`,
'A kept activation is divided by the keep probability; a dropped one is zero.',
[s('When kept, use inverted scaling.',T`\tilde h=\frac4{1/2}=8`),s('When dropped, the output is 0. Average over the two equally likely masks.',T`\mathbb E[\tilde h]=\frac12(8)+\frac12(0)=4`),s('At ordinary evaluation, disable the mask and do not apply another scaling step. The activation is 4.')],
'Inverted scaling preserves the expected activation under the mask; it does not make each training pass equal to evaluation.',
'The deck’s p means keep probability. An API’s dropout probability may instead mean the probability of dropping.',
{problem:T`An API specifies drop rate $1/4$. For $h=3$, find the keep probability, kept training value and expectation under inverted dropout.`,solution:[s('Convert drop rate to keep probability.',T`p=1-\frac14=\frac34`),s('Scale only the kept activation.',T`\tilde h_{\rm kept}=\frac3{3/4}=4,\qquad\mathbb E[\tilde h]=\frac34(4)+\frac14(0)=3`)]}),
E(12,'Average held-out folds correctly',44,
T`Use four equal-sized folds on 100 development examples. Held-out accuracies are $3/4,1/2,3/4,1$. Compute the mean and the number of training and validation examples per fit.`,
'Each row of the fold diagram is a fresh fit, not continued training.',
[s('Add the four scores.',T`\frac34+\frac12+\frac34+1=3`),s('Divide by four.',T`\overline s=\frac34`),s('Each fold contains 25 examples. Each fit trains on 75 and validates on 25; four fresh fits are needed per candidate.')],
'Cross-validation estimates development performance while reusing the limited dataset across separate training/validation roles.',
'Do not fit preprocessing globally or carry trained weights from one fold into the next.',
{problem:'Several photos come from each patient. A classmate randomly splits individual photos across folds. What should change, and why?',solution:[s('Keep each patient’s related samples within one fold using a group-aware split.'),s('Otherwise the model may see patient-specific information during training that also appears in validation, overstating generalization to new patients.')]})
];

const Q=(topic,type,prompt,answer,check)=>({id:`reg-${topic}-${type}`,topic,type,prompt,answer,check});
export const questions=[
Q(0,'flashcard','What is generalization?','Performance on unseen examples from the relevant distribution, beyond fitting the observed training set.','Distinguish training fit from unseen-data performance.'),
Q(0,'computation','A has train/validation errors 1/6; B has 3/4. Which is preferred on this validation split?','B, because its validation error 4 is lower than 6. A has better training fit but worse held-out performance.','Use the validation metric for selection.'),
Q(0,'theory','Why might a high-capacity model overfit, and does it always do so?','It can fit sample-specific noise and accidental patterns. It does not always overfit; data size, regularization, task structure and optimization also matter.','Include both the mechanism and the qualification.'),
Q(1,'flashcard','How do L1 and L2 penalties differ?','L1 sums absolute weights and can encourage sparsity. L2 sums squared weights and imposes a gradient proportional to each weight.','Distinguish sparsity from shrinkage.'),
Q(1,'computation',T`For data loss 3, $\theta=(1,2)$ and $\lambda=1/5$, compute $J=L+\lambda\|\theta\|^2$.`,T`The squared-weight sum is $1+4=5$, so $J=3+(1/5)5=4$.`,'Do not confuse the sum of squares with the norm’s square root.'),
Q(1,'theory','Why can too much regularization lead to underfitting?','It can make genuine signal too expensive or restrict the learned solution too strongly, raising both training and validation error.','Stronger is not always better.'),
Q(2,'flashcard','Why does negative log-likelihood use a sum?','Conditional independence factorizes likelihood into a product; log turns the product into a sum, and the minus sign turns maximization into minimization.','Name both independence and the log identity.'),
Q(2,'computation',T`Which likelihood is larger: $(1/2)(1/4)$ or $(1/4)(1/4)$? Which NLL is smaller?`,T`The first is $1/8$ versus $1/16$, so the first has greater likelihood and smaller NLL.`,'No numerical logarithms are needed.'),
Q(2,'theory','When can Gaussian regression NLL be minimized by minimizing squared error?','When the conditional mean model is fixed in form, observations are conditionally independent, and the positive residual variance is held fixed. Then the NLL differs from SSE by a positive scale and an additive constant.','The normalization term matters if variance is optimized.'),
Q(3,'flashcard','What distinguishes MAP from MLE?','MLE uses the likelihood. MAP combines likelihood and a parameter prior, selecting a posterior mode.','Do not confuse the posterior with the likelihood.'),
Q(3,'computation',T`For isotropic prior variance $\tau^2=1$, what is the coefficient of $\|\theta\|^2$ in the negative log-prior?`,T`It is $1/(2\tau^2)=1/2$, before rescaling the data loss.`,'State the isotropic Gaussian assumption.'),
Q(3,'theory','Does a general zero-mean Gaussian prior always produce scalar L2 shrinkage?','Its negative log-density has a quadratic term involving inverse covariance. It reduces to a scalar times the squared Euclidean norm for isotropic covariance.','Explain the covariance restriction.'),
Q(4,'flashcard','What is label-preserving augmentation?','A transformation that leaves the target valid, or changes the target annotation consistently with the transformed input.','Spatial labels may need transforming too.'),
Q(4,'computation','An 8-unit-wide coordinate system uses reflection x′ = 8 − x. A box spans [2,5]. Find the reflected interval.','The new ordered interval is [8−5, 8−2] = [3,6].','Reflect both endpoints and reorder.'),
Q(4,'theory','Why should augmented copies of one image stay in the same dataset split?','Copies share information with the original. Splitting related variants across training and validation can leak that information and inflate apparent generalization.','Split original groups before augmentation.'),
Q(5,'flashcard','What distinguishes MixUp, CutOut and CutMix?','MixUp blends inputs and labels; CutOut erases a region and usually keeps the original label; CutMix pastes a patch and mixes labels by contributed area.','Include both the input and target operations.'),
Q(5,'computation',T`Mix labels $(1,0)$ and $(0,1)$ with $\lambda=1/4$. What is the soft target?`,T`It is $(1/4,3/4)$.`,'Maintain the stated class order.'),
Q(5,'theory','Why should CutMix use actual patch area after clipping?','A patch clipped at an image boundary contributes less than its nominal rectangle. The target weights should match the actual source areas in the constructed input.','Distinguish proposed and realized area.'),
Q(6,'flashcard','What is the main distinction between AgMax and RandAugment?','AgMax encourages agreement between augmented views; RandAugment selects and combines augmentation operations.','Separate an agreement constraint from an augmentation policy.'),
Q(6,'computation','Two views of a cat both receive prediction (1,0) in bird/cat order. Do they agree, and are they correct?','They agree exactly and are both wrong: they predict bird.','Agreement does not imply correctness.'),
Q(6,'theory','Why is a constant prediction a warning for agreement-only learning?','It can satisfy consistency on every pair without learning information that distinguishes classes. A useful task-learning signal is still needed.','Explain the trivial solution.'),
Q(7,'flashcard','How do input noise and weight noise differ?','Input noise perturbs the observed data; weight noise perturbs the parameterized mapping. Both can encourage robustness under appropriate perturbation assumptions.','Identify what is perturbed.'),
Q(7,'computation',T`With $f(x;w)=wx$, $x=2$ and $w=3$, what prediction follows a weight perturbation of $-1/2$?`,T`The perturbed weight is $5/2$ and the prediction is 5.`,'Perturb the weight before multiplying.'),
Q(7,'theory','Why does domain randomization sometimes help simulation-to-real transfer?','Varied simulated conditions discourage reliance on one simulator-specific appearance or setting. Transfer still depends on the coverage and relevance of that variation.','Include the limitation.'),
Q(8,'flashcard','What is shared in multi-task learning?','Often a backbone representation and its parameters, while separate heads serve each task.','Distinguish shared and task-specific parameters.'),
Q(8,'computation',T`Task losses are 4 and 2, weighted by $1/2$ and 1. Find their weighted sum.`,T`The objective is $(1/2)4+2=4$.`,'Weight before adding.'),
Q(8,'theory','What is negative transfer?','Learning one task harms another because the shared representation or updates are incompatible.','More tasks do not automatically improve generalization.'),
Q(9,'flashcard','Do identical branch architectures imply parameter sharing?','No. The actual weights must be tied, not merely arranged in the same architecture.','Differentiate architecture reuse from weight tying.'),
Q(9,'computation','Two encoders each use 8 parameters; a separate head uses 3. Count parameters with independent and tied encoders.','Independent: 8+8+3 = 19. Tied: 8+3 = 11.','Count distinct trainable values.'),
Q(9,'theory','Can shared encoders produce different outputs?','Yes. They implement the same function, but different inputs can map to different representations.','Sharing does not require equal activations.'),
Q(10,'flashcard','Which checkpoint should early stopping normally return?','The best checkpoint according to the chosen validation metric, rather than automatically the final checkpoint.','Separate stopping time from best checkpoint.'),
Q(10,'computation','Validation losses are 4,2,3,4 with patience 2 and strict improvement. When do we stop and what do we restore?','Stop at epoch 4 after two non-improvements; restore epoch 2 with loss 2.','Use the stated patience and tie convention.'),
Q(10,'theory','Why should the test set not control early stopping?','Repeated checkpoint selection would adapt the training process to the test set, undermining its role as an untouched final evaluation.','Use validation data instead.'),
Q(11,'flashcard','In slide 43, does p mean drop or keep probability?','Keep probability. Drop probability is 1−p.','An API may use the opposite naming convention.'),
Q(11,'computation',T`For inverted dropout with $h=2$ and keep probability $p=1/2$, what are the kept value and expectation?`,T`The kept value is 4; the expectation is $(1/2)4+(1/2)0=2$.`,'Do not scale again during ordinary evaluation.'),
Q(11,'theory','Why can dropout reduce overfitting?','Randomly absent activations discourage brittle co-adaptation, requiring useful features under varied subsets of available units.','Too much dropout can also underfit.'),
Q(12,'flashcard','Why reinitialize the model for each cross-validation fold?','Each held-out evaluation must come from a model trained without that fold. Carrying weights across folds leaks information.','Treat folds as separate fits.'),
Q(12,'computation','Four equal folds produce scores 1/2,1/2,1,1. What is the mean?','The sum is 3; the mean is 3/4.','Divide by the number of folds.'),
Q(12,'theory','Where should normalization be fitted during cross-validation?','Inside each training fold, then applied to that fold’s validation data.','Avoid using held-out statistics during fitting.')
];
